-- 신조어 5개 추가 (2026-09-09 아침 검수, 운영자 승인 4·5·8·10·11번).
-- 후보 테이블(slang_candidates)에서 승격: 갓반인·오조오억·오픈런·멘고멘고·델룰루.
-- 검수 시 짚은 점 — 운영자가 확인하고 승인한 사항이다:
--   갓반인 — 뜻은 출처 4개가 일치하나 언론·나무위키 급 문서가 없어 최초 사용 시점·발원지를
--     특정할 자료가 없다. origin에 확정된 기록이 없다는 사실을 그대로 적었다.
--   오조오억 — 2021년 남혐 논란에 휘말린 표현. 표현 자체에 혐오 의미는 없다는 것이 한국일보·
--     나무위키 공통 서술이라 origin/usage에 논란 사실을 숨기지 않고 적었다.
--   멘고멘고 — 이번 수집분에서 검증이 가장 약하다. 사전·언론 문서가 없고 X·인스티즈·스레드 등
--     개인 게시물이 주 출처이며, 일본어 ごめん 유래라는 점만 공통이고 일본 실사용인지 온라인
--     변형인지 출처마다 주장이 갈려 origin에 두 주장을 병기했다. 예문도 검증된 용례가 적어 1개다.
--   델룰루 — 표기가 델룰루/딜루루/딜룰루로 갈려 나무위키 문서명인 델룰루를 표제어로 잡고
--     나머지를 aliases에 넣었다.
-- 보류(이번에 올리지 않음): 홀리몰리·신박하다·꼰대·플렉스·지리다 — 후보 테이블에 그대로 둔다.
-- 뽀시래기는 사전이 아니라 홈의 '오늘의 실전 표현'(dailyPicks.ts)으로 보냈다
-- (20260908100000의 라떼는 말이야와 같은 처리).
--
-- pronunciation은 draft_payload에 없어 표준 발음으로 채웠다 — 특히 갓반인 [갇빠닌] 확인 요망.
--
-- id는 439부터 (기존 최대 438).
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.
--
-- NOTE: 이 파일의 값은 slang_candidates.draft_payload에서 그대로 뽑아 쓴 것이며, 운영 DB에는
-- 같은 payload를 직접 읽는 등가 SQL(add_five_slang_words)로 적용했다. 적용 후 words 행과
-- 이 파일의 값이 일치하는지 대조해 확인했다. 이 파일은 자립적인 스냅샷이라 단독 재적용도 가능하다.

begin;

insert into public.words (id, word, category, short_desc, pronunciation, short_desc_i18n, origin, origin_i18n, usage, usage_i18n, romanization, meanings, related_words, aliases, likes, saves, translations) values
('439', '갓반인', 'new-slang', '연예인급으로 뛰어난 일반인', '[갇빠닌]', '{"de": "Ein „Normalo“ auf Promi-Niveau", "en": "An ordinary person who''s absurdly impressive", "es": "Una persona común que impresiona como una famosa", "ja": "芸能人級にすごい一般人", "vi": "Người thường nhưng giỏi/đẹp như sao"}'::jsonb, '「갓(God)+일반인」의 합성어로, 「갓생」·「갓벽」처럼 한국 인터넷에서 폭넓게 쓰이는 접두사 「갓-」 계열 조어다. 특정 방송이나 인물에서 시작됐다는 확정된 기록은 없고, 커뮤니티와 SNS에서 자연스럽게 굳은 말로 보인다.', '{"de": "Eine Zusammensetzung aus dem englischen „God“ und 일반인, Teil der großen 갓--Präfixfamilie, zu der auch 갓생 und 갓벽 gehören. Es gibt keinen gesicherten Beleg für einen Ursprung in einer bestimmten Sendung oder Person; es scheint sich organisch in Communitys und sozialen Medien gefestigt zu haben.", "en": "A compound of English “God” and 일반인, part of the broad 갓- prefix family that also gives 갓생 and 갓벽. There''s no confirmed record of it starting from a specific show or person; it appears to have settled in organically across communities and social media.", "es": "Compuesto del inglés “God” y 일반인, dentro de la amplia familia del prefijo 갓- que también da 갓생 y 갓벽. No hay constancia de que naciera en un programa o de una persona concreta; parece haberse asentado de forma orgánica en foros y redes.", "ja": "英語のGodと「一般人」の合成語で、「カッセン」「カッピョク」と同じく韓国のネットで広く使われる接頭辞「カッ-」系の造語。特定の番組や人物から始まったという確定的な記録はなく、コミュニティやSNSで自然に定着した語とみられる。", "vi": "Ghép “God” tiếng Anh với 일반인, thuộc họ tiền tố 갓- rất phổ biến, cũng sinh ra 갓생 và 갓벽. Không có ghi nhận chắc chắn nào cho thấy nó khởi từ một chương trình hay nhân vật cụ thể; có vẻ nó tự định hình trên các diễn đàn và mạng xã hội."}'::jsonb, '칭찬이고 부러움이다. 대상 본인에게 직접 「갓반인이시네요」라고 해도 무례하지 않다. 「일반인」의 격을 올리는 말이라, 이미 연예인이거나 프로인 사람에게는 쓰지 않는다.', '{"de": "Lob mit einer Prise Neid; man kann es jemandem direkt sagen (갓반인이시네요), ohne unhöflich zu wirken. Da es 일반인 („keine Promi“) aufwertet, benutzt man es nicht für Menschen, die ohnehin Promis oder Profis sind.", "en": "It''s praise mixed with envy, and it''s not rude to say 갓반인이시네요 straight to the person. Because it works by elevating 일반인 (“non-celebrity”), it isn''t used for people who are already celebrities or professionals.", "es": "Es elogio con una pizca de envidia, y no resulta grosero decírselo a la cara (갓반인이시네요). Como funciona elevando la categoría de 일반인 (“no famoso”), no se usa con quien ya es famoso o profesional.", "ja": "褒め言葉であり羨望でもある。本人に直接「カッパニンですね」と言っても失礼にはならない。「一般人」の格を上げる言葉なので、すでに芸能人やプロの人には使わない。", "vi": "Vừa khen vừa ngưỡng mộ, và nói thẳng với người ta (갓반인이시네요) cũng không bất lịch sự. Vì nó nâng bậc chữ 일반인 (“người không nổi tiếng”), nên không dùng cho người đã là nghệ sĩ hay dân chuyên nghiệp."}'::jsonb, 'Gat-Ban-In', '[{"type": "합성어", "examples": [{"de": "Diese Person ist kein normaler Mensch … das hat sie als Hobby gemalt?", "es": "Esta persona no es una anónima cualquiera… ¿dibujó eso como hobby?", "ja": "この人、一般人のレベルじゃない…趣味で描いたって本当?", "vi": "Người này đâu phải dân thường… vẽ cái đó chỉ vì sở thích thôi á?", "eng": "This person is next-level for a non-pro — they drew that as a hobby?", "kor": "이분 갓반인이다… 취미로 그렸다는 게 말이 돼?"}, {"de": "Meine Freundin ist so god-tier, dass ich neben ihr schäbig wirke haha", "es": "Mi amiga es tan god-tier que a su lado me siento poca cosa jaja", "ja": "友達が一般人離れしてて、一緒にいると自分がみすぼらしく感じるw", "vi": "Bạn mình xịn quá mức người thường, đi cùng là mình thấy mình xoàng hihi", "eng": "My friend is such a god-tier normie that I feel shabby next to them lol", "kor": "친구가 갓반인이라 같이 다니면 내가 초라해져 ㅋㅋ"}], "definition": "영어 God과 「일반인」을 붙인 말. 연예인이 아닌데도 외모·실력·삶의 질이 부러울 만큼 뛰어난 사람을 치켜세워 부른다. 「일반인」이 그냥 평범한 사람이라는 뜻이니, 앞에 갓-을 붙여 격을 한 단계 올린 셈이다.", "definition_i18n": {"de": "Das englische „God“ an 일반인 („gewöhnliche Person“) geklebt. Ein Ausdruck der Bewunderung für jemanden, der kein Promi ist, aber beneidenswertes Aussehen, Können oder Lebensqualität hat. Da 일반인 einfach eine normale Person meint, hebt das Präfix 갓- sie eine Stufe höher.", "en": "English “God” glued onto 일반인 (“ordinary person”). It''s a term of admiration for someone who isn''t a celebrity yet has enviable looks, skill or quality of life. Since 일반인 just means a regular person, the 갓- prefix bumps them up a tier.", "es": "El “God” inglés pegado a 일반인 (“persona corriente”). Es un término de admiración para quien, sin ser famoso, tiene un físico, una habilidad o una vida envidiables. Como 일반인 significa simplemente alguien normal, el prefijo 갓- le sube un escalón.", "ja": "英語のGodと「一般人」をくっつけた語。芸能人ではないのに、容姿・実力・生活の質がうらやましいほど優れた人を持ち上げて呼ぶ。「一般人」がただの普通の人という意味なので、頭に「カッ(神)」を付けて格を一段上げた形。", "vi": "Ghép “God” tiếng Anh vào 일반인 (“người thường”). Đây là cách gọi đầy ngưỡng mộ dành cho người không phải nghệ sĩ nhưng có ngoại hình, tài năng hay chất lượng sống đáng thèm muốn. Vì 일반인 chỉ nghĩa là người bình thường, tiền tố 갓- nâng họ lên một bậc."}}]'::jsonb, array['갓생','갓벽','인싸'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "God-tier ordinary person"}, {"lang": "🇯🇵 JA", "text": "神一般人"}, {"lang": "🇨🇳 ZH", "text": "神级素人"}, {"lang": "🇻🇳 VI", "text": "Người thường đẳng cấp thần"}, {"lang": "🇪🇸 ES", "text": "Anónimo de nivel dios"}, {"lang": "🇩🇪 DE", "text": "Göttlicher Normalo"}]'::jsonb),
('440', '오조오억', 'new-slang', '셀 수 없이 많다는 과장 표현', '[오조오억]', '{"de": "Eine absurd große Zahl für „unzählig“", "en": "An absurdly huge number, meaning “countless”", "es": "Una cifra absurda que significa “incontable”", "ja": "数えきれないほど多いという誇張表現", "vi": "Con số phóng đại nghĩa là “vô số”"}'::jsonb, '2017년 Mnet 「프로듀스 101 시즌2」 7회의 「Get Ugly」 무대 영상에 달린 댓글이 베스트 댓글이 되면서 유행어가 됐다. 이후 동원참치 TV 광고에 쓰이며 더 널리 퍼졌다. 다만 2021년 무렵 일부 여초 커뮤니티에서 남성 비하 맥락으로 쓰인다는 지적이 나오며 남혐 논란에 휘말렸다. 표현 자체에 혐오 의미가 담긴 것은 아니라는 게 언론과 사전류의 공통 설명이지만, 이후 부담스러워하는 사람이 생겼다.', '{"de": "Es wurde 2017 zum Schlagwort, nachdem ein Kommentar unter dem „Get Ugly“-Bühnenvideo aus Folge 7 von Mnets Produce 101 Staffel 2 zum Top-Kommentar aufstieg. Ein Dongwon-Thunfisch-Werbespot verbreitete es weiter. Um 2021 geriet es allerdings in eine Misandrie-Debatte: Kritiker sagten, einige überwiegend weibliche Communitys nutzten es herabsetzend gegenüber Männern. Presse und Nachschlagewerke sind sich einig, dass der Ausdruck selbst keine Hassbedeutung trägt, doch seither ist er manchen unangenehm.", "en": "It became a catchphrase in 2017 after a comment on the “Get Ugly” stage video from episode 7 of Mnet''s Produce 101 Season 2 rose to top comment. A Dongwon tuna TV ad later spread it further. Around 2021, however, it was pulled into a misandry dispute after critics said some women-majority communities used it to disparage men. Press and reference sources agree the phrase itself carries no hateful meaning, but some people have been uneasy with it since.", "es": "Se hizo popular en 2017, cuando un comentario en el vídeo de la actuación “Get Ugly” del episodio 7 de Produce 101 Temporada 2 (Mnet) llegó a comentario destacado. Un anuncio de atún Dongwon lo difundió aún más. Sin embargo, hacia 2021 quedó envuelto en una polémica de misandria: se dijo que algunas comunidades mayoritariamente femeninas lo usaban para menospreciar a los hombres. Prensa y obras de referencia coinciden en que la expresión no tiene carga de odio, pero desde entonces a algunas personas les incomoda.", "ja": "2017年、Mnet「PRODUCE 101 シーズン2」7話の「Get Ugly」ステージ映像に付いたコメントがベストコメントになって流行語化した。その後、東遠ツナのCMに使われてさらに広まった。ただし2021年ごろ、一部の女性中心コミュニティで男性を貶す文脈に使われるという指摘が出て「男性嫌悪」論争に巻き込まれた。表現自体に嫌悪の意味はないというのが報道や事典類の共通説明だが、以後、負担に感じる人も生まれた。", "vi": "Nó thành câu cửa miệng từ 2017, sau khi một bình luận dưới video sân khấu “Get Ugly” tập 7 của Produce 101 mùa 2 (Mnet) lên top. Quảng cáo cá ngừ Dongwon sau đó khiến nó lan rộng hơn. Tuy vậy, khoảng 2021 nó bị cuốn vào tranh cãi “ghét đàn ông” khi có ý kiến cho rằng vài cộng đồng đông nữ dùng nó để hạ thấp nam giới. Báo chí và các nguồn tra cứu đều nói bản thân cụm từ không mang nghĩa thù ghét, nhưng từ đó một số người thấy khó chịu với nó."}'::jsonb, '숫자 자리에 넣어 「오조오억 번」, 명사 뒤에 붙여 「귀여움 오조오억」처럼 쓴다. 팬덤 댓글에서 특히 흔하다. 다만 남혐 논란을 겪은 말이라 처음 보는 사이나 남녀가 섞인 공개된 자리에서는 피하는 사람도 있다.', '{"de": "Man setzt es in eine Zählung (오조오억 번) oder hinter ein Nomen (귀여움 오조오억). Besonders häufig in Fandom-Kommentaren. Weil es eine Misandrie-Kontroverse durchlaufen hat, meiden es manche gegenüber Fremden oder in gemischten öffentlichen Runden.", "en": "Drop it into a count (오조오억 번) or after a noun (귀여움 오조오억). It''s especially common in fandom comments. Because it went through a misandry controversy, though, some people avoid it with strangers or in mixed public settings.", "es": "Se mete en un recuento (오조오억 번) o detrás de un sustantivo (귀여움 오조오억). Es habitual sobre todo en comentarios de fandom. Como pasó por una polémica de misandria, hay quien lo evita con desconocidos o en espacios públicos mixtos.", "ja": "回数に入れて「五兆五億回」、名詞の後ろに付けて「かわいさ五兆五億」のように使う。ファンダムのコメントで特に多い。ただし男性嫌悪論争を経た語なので、初対面の相手や男女が混じる公開の場では避ける人もいる。", "vi": "Cho vào số lần (오조오억 번) hoặc đặt sau danh từ (귀여움 오조오억). Rất hay gặp trong bình luận fandom. Nhưng vì từng dính tranh cãi ghét đàn ông, một số người tránh dùng với người lạ hoặc nơi công cộng có cả nam lẫn nữ."}'::jsonb, 'O-Jo-O-Eok', '[{"type": "명사(수 표현)", "examples": [{"de": "Diese Bühnenperformance hab ich fünf Billionen Mal geschaut.", "es": "He revisto esta actuación cinco billones de veces.", "ja": "このステージ、五兆五億回は見返した。", "vi": "Sân khấu này mình tua lại năm nghìn tỉ lần rồi.", "eng": "I''ve rewatched this performance like five trillion times.", "kor": "이 무대 오조오억 번 돌려봤어."}, {"de": "Dein Gesichtsausdruck heute hat fünf Billionen Einheiten Süßigkeit.", "es": "Tu cara de hoy tiene cinco billones de puntos de ternura.", "ja": "今日の表情、かわいさが五兆五億ある。", "vi": "Biểu cảm hôm nay dễ thương cỡ năm nghìn tỉ luôn.", "eng": "Your face today has like five trillion units of cute in it.", "kor": "오늘 표정 진짜 귀여움이 오조오억이다."}], "definition": "5조 5억이라는 실제 숫자를 그대로 읽은 말이지만, 정확한 수가 아니라 「엄청나게 많다」는 뜻으로 쓴다. 「오조오억 번 봤다」처럼 횟수를 부풀리거나 「매력이 오조오억」처럼 정도를 부풀린다.", "definition_i18n": {"de": "Wörtlich die laut gelesene Zahl 5.000.500.000.000, aber nie eine echte Zählung — es heißt „irrsinnig viel“. Man bläst eine Anzahl auf (오조오억 번, „fünf Billionen Mal“) oder einen Grad (매력이 오조오억).", "en": "Literally the number 5,000,500,000,000 read aloud, but it never means a real count — it means “an insane amount.” You inflate a tally (오조오억 번, “five trillion times”) or a degree (매력이 오조오억, “five trillion units of charm”).", "es": "Literalmente la cifra 5.000.500.000.000 leída en voz alta, pero nunca indica una cuenta real: significa “una barbaridad”. Se infla un recuento (오조오억 번, “cinco billones de veces”) o un grado (매력이 오조오억).", "ja": "5兆5億という数字をそのまま読んだ語だが、正確な数ではなく「とんでもなく多い」の意味で使う。「五兆五億回見た」のように回数を盛ったり、「魅力が五兆五億」のように程度を盛ったりする。", "vi": "Đúng nghĩa đen là con số 5.000.500.000.000 đọc lên, nhưng không bao giờ chỉ số đếm thật — nó nghĩa là “nhiều kinh khủng”. Người ta thổi phồng số lần (오조오억 번) hoặc mức độ (매력이 오조오억)."}}]'::jsonb, array['최애','과몰입','떡밥'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "A gazillion (countless)"}, {"lang": "🇯🇵 JA", "text": "五兆五億(数えきれない)"}, {"lang": "🇨🇳 ZH", "text": "五兆五亿(数不清)"}, {"lang": "🇻🇳 VI", "text": "Năm nghìn tỉ (vô số)"}, {"lang": "🇪🇸 ES", "text": "Cinco billones (un montón)"}, {"lang": "🇩🇪 DE", "text": "Fünf Billionen (unzählig)"}]'::jsonb),
('441', '오픈런', 'new-slang', '문 열자마자 달려가 사는 것', '[오픈런]', '{"de": "Losrennen, sobald geöffnet wird", "en": "Sprinting in the second the doors open", "es": "Correr en cuanto abren para comprar", "ja": "開店と同時に走って買うこと", "vi": "Chạy vào mua ngay khi cửa vừa mở"}'::jsonb, '영어 open run은 원래 끝나는 날을 정하지 않고 계속 올리는 공연 방식(리미티드 런의 반대)을 가리키는 말이다. 한국에서는 그 뜻과 무관하게 「열자마자 달린다」는 뜻으로 굳었고, 이렇게 쓰는 것은 한국에서만 통하는 콩글리시다. 영어로 같은 상황은 opening rush 정도로 옮긴다. 2020년대 초 명품 매장 대기 줄을 다룬 기사에 자주 등장했다.', '{"de": "Im Englischen bezeichnet open run eine Aufführung ohne festgelegtes Enddatum, das Gegenteil eines limited run. Das Koreanische hat eine völlig unabhängige Bedeutung festgeschrieben — „losrennen, sobald geöffnet ist“ — und ist damit Konglish, das nur in Korea funktioniert; im Englischen hieße die Situation eher opening rush. In Berichten über Warteschlangen vor Luxusgeschäften tauchte es Anfang der 2020er ständig auf.", "en": "In English an open run means a show staged with no set closing date, the opposite of a limited run. Korean fixed on a completely unrelated sense — “run the moment it opens” — making it Konglish that only works in Korea; the English for the same situation is closer to an opening rush. It appeared constantly in early-2020s coverage of luxury-store queues.", "es": "En inglés, open run designa una función sin fecha de cierre fijada, lo contrario de un limited run. El coreano fijó un sentido sin relación alguna —“correr en cuanto abre”—, así que es konglish que solo funciona en Corea; en inglés la situación se diría más bien opening rush. Apareció sin parar en la prensa de comienzos de los 2020 sobre las colas ante tiendas de lujo.", "ja": "英語のopen runは本来、終演日を決めずに続ける公演方式(リミテッド・ランの反対)を指す。韓国ではその意味とは関係なく「開いた瞬間に走る」という意味で定着し、この用法は韓国だけで通じるコングリッシュ。同じ状況は英語ではopening rush程度に訳す。2020年代前半、ブランド店の行列を扱った記事に頻繁に登場した。", "vi": "Trong tiếng Anh, open run chỉ suất diễn không ấn định ngày kết thúc, ngược với limited run. Tiếng Hàn lại cố định một nghĩa chẳng liên quan — “mở cửa là chạy” — nên đây là Konglish chỉ hiểu được ở Hàn; tiếng Anh cho tình huống này gần với opening rush hơn. Nó xuất hiện liên tục trên báo chí đầu thập niên 2020 về hàng dài trước các cửa hàng xa xỉ."}'::jsonb, '「오픈런하다」로 동사처럼 쓴다. 사고 싶은 물건이 있는데 수량이 적을 때의 각오를 표현한다. 한국에서 만들어진 영어라서 영어권 사람에게 그대로 말하면 못 알아듣는다.', '{"de": "Wird verbal als 오픈런하다 gebraucht. Es drückt die Entschlossenheit aus, wenn das Gewünschte knapp ist. Da es in Korea geprägtes Englisch ist, versteht es ein englischer Muttersprachler so nicht.", "en": "Used verbally as 오픈런하다. It conveys the resolve you need when what you want is scarce. Since it''s English coined in Korea, saying it as-is to an English speaker won''t land.", "es": "Se usa como verbo: 오픈런하다. Expresa la determinación necesaria cuando lo que quieres escasea. Al ser inglés inventado en Corea, decírselo tal cual a un angloparlante no se entiende.", "ja": "「オープンランする」と動詞のように使う。買いたい物があるのに数が少ないときの覚悟を表す。韓国で作られた英語なので、英語圏の人にそのまま言っても通じない。", "vi": "Dùng như động từ: 오픈런하다. Nó diễn tả quyết tâm khi thứ bạn muốn có rất ít hàng. Vì là tiếng Anh do người Hàn tạo ra, nói nguyên vậy với người nói tiếng Anh sẽ không hiểu."}'::jsonb, 'O-Peun-Reon', '[{"type": "명사", "examples": [{"de": "Bei dem Pop-up bekommt man angeblich nichts, wenn man nicht vor der Öffnung ansteht.", "es": "Dicen que en esa pop-up no pillas nada si no haces open run.", "ja": "あのポップアップ、オープンランしないと買えないらしい。", "vi": "Nghe nói pop-up đó không xếp hàng từ sớm thì không mua được.", "eng": "They say you can''t get one at that pop-up unless you do an open run.", "kor": "그 팝업 오픈런 안 하면 못 산대."}, {"de": "Ab 6 Uhr angestanden — und trotzdem 30 Leute vor mir.", "es": "Hice open run desde las 6 de la mañana y aun así tenía 30 personas delante.", "ja": "朝6時からオープンランしたのに、前に30人いた。", "vi": "Xếp hàng từ 6 giờ sáng mà phía trước vẫn còn 30 người.", "eng": "I lined up from 6 a.m. for the open run and there were still 30 people ahead of me.", "kor": "새벽 6시부터 오픈런했는데 앞에 30명."}], "definition": "매장이 문을 열기 전부터 줄을 섰다가, 열리는 순간 달려가 물건을 사거나 자리를 잡는 것. 명품·한정판·인기 맛집·팝업스토어에서 흔하다. 국립국어원은 다듬은 말로 「개장 질주」를 제시했다.", "definition_i18n": {"de": "Vor der Öffnung eines Geschäfts anstehen und im Moment der Öffnung hineinstürmen, um etwas zu kaufen oder einen Platz zu ergattern. Üblich bei Luxusboutiquen, limitierten Drops, angesagten Restaurants und Pop-up-Stores. Das Nationale Institut für Koreanische Sprache schlägt als klares Koreanisch 개장 질주 („Eröffnungssprint“) vor.", "en": "Queueing before a store opens and then rushing in the moment it does, to buy something or claim a spot. Common at luxury boutiques, limited drops, popular restaurants and pop-up stores. The National Institute of Korean Language proposes 개장 질주 (“opening dash”) as the plain-Korean alternative.", "es": "Hacer cola antes de que abra una tienda y entrar corriendo en cuanto abre, para comprar algo o pillar sitio. Habitual en boutiques de lujo, ediciones limitadas, restaurantes de moda y pop-ups. El Instituto Nacional de la Lengua Coreana propone 개장 질주 (“carrera de apertura”) como alternativa en coreano llano.", "ja": "店が開く前から並び、開いた瞬間に走って商品を買ったり席を確保したりすること。ブランド店・限定品・人気飲食店・ポップアップストアでよく見られる。国立国語院は言い換え語として「開場疾走」を提示している。", "vi": "Xếp hàng trước khi cửa hàng mở rồi lao vào ngay khi mở, để mua đồ hoặc giành chỗ. Thường gặp ở cửa hàng hàng hiệu, hàng giới hạn, quán ăn hot và pop-up store. Viện Quốc ngữ Hàn Quốc đề xuất từ thuần Hàn thay thế là 개장 질주 (“chạy nước rút lúc mở cửa”)."}}]'::jsonb, array['굿즈','예판','인생샷'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Opening rush (queue-and-sprint)"}, {"lang": "🇯🇵 JA", "text": "オープンラン(開店ダッシュ)"}, {"lang": "🇨🇳 ZH", "text": "开门冲刺抢购"}, {"lang": "🇻🇳 VI", "text": "Xếp hàng chờ mở cửa để mua"}, {"lang": "🇪🇸 ES", "text": "Carrera de apertura"}, {"lang": "🇩🇪 DE", "text": "Öffnungs-Sturm"}]'::jsonb),
('442', '멘고멘고', 'new-slang', '장난스럽게 「미안」이라고 할 때', '[멘고멘고]', '{"de": "Eine verspielte Art, sich zu entschuldigen", "en": "A playful way to say sorry", "es": "Una forma juguetona de pedir perdón", "ja": "ふざけて「ごめん」と言うときの言い方", "vi": "Cách nói xin lỗi kiểu đùa"}'::jsonb, '일본어 「ごめん」에서 왔다는 설명이 대부분이지만, 누가 언제부터 「멘고멘고」 형태로 쓰기 시작했는지 확인되는 자료가 없다. 일본어권에서 실제로 쓰는 표현이라는 주장과, 한국·일본 온라인 커뮤니티에서 놀이처럼 만들어진 변형이라는 주장이 함께 있다. 확정된 어원으로 보기 어렵다.', '{"de": "Fast alle Erklärungen führen es auf das japanische ごめん (gomen, „Entschuldigung“) zurück, doch es gibt keinen überprüfbaren Beleg, wer wann anfing, 멘고멘고 zu sagen. Manche behaupten, Japanischsprechende benutzten es wirklich; andere halten es für eine spielerische Form aus koreanischen und japanischen Onlineforen. Die Etymologie gilt nicht als gesichert.", "en": "Most explanations trace it to Japanese ごめん (gomen, “sorry”), but there''s no verifiable record of who started saying it as 멘고멘고 or when. Some claim Japanese speakers genuinely use it; others say it''s a playful form coined in Korean and Japanese online communities. The etymology should not be treated as settled.", "es": "Casi todas las explicaciones lo remontan al japonés ごめん (gomen, “perdón”), pero no hay registro verificable de quién empezó a decir 멘고멘고 ni cuándo. Unos sostienen que los japoneses lo usan de verdad; otros, que es una forma juguetona nacida en foros coreanos y japoneses. No conviene darlo por etimología cerrada.", "ja": "日本語の「ごめん」由来という説明が大半だが、誰がいつから「メンゴメンゴ」の形で使い始めたのかを確認できる資料がない。日本語圏で実際に使う表現だという主張と、韓国・日本のオンラインコミュニティで遊びとして作られた変形だという主張が併存する。確定した語源とは言いがたい。", "vi": "Hầu hết cách giải thích truy về tiếng Nhật ごめん (gomen, “xin lỗi”), nhưng không có tài liệu kiểm chứng được ai bắt đầu nói 멘고멘고 và từ khi nào. Có ý kiến nói người Nhật dùng thật; ý kiến khác cho rằng đây là dạng chơi chữ sinh ra trên các diễn đàn Hàn và Nhật. Không nên coi từ nguyên này là đã xác định."}'::jsonb, '가벼운 상황에서만 쓴다. 실제로 잘못한 일이나 사과가 필요한 자리에 쓰면 성의 없어 보인다. 일본어에서 온 유행어라 뜻을 모르는 사람도 많다.', '{"de": "Nur für harmlose Situationen. Wo eine echte Entschuldigung nötig ist, wirkst du damit leichtfertig. Als japanischstämmiges Modewort kennen es viele nicht.", "en": "Only for light situations. Use it where a real apology is called for and you''ll come off as flippant. Being a Japanese-derived fad word, plenty of people won''t know it.", "es": "Solo para situaciones leves. Si lo usas donde hace falta una disculpa de verdad, sonarás frívolo. Al ser una palabra de moda de origen japonés, mucha gente no la conoce.", "ja": "軽い場面でのみ使う。実際に非がある場面や謝罪が必要な場で使うと誠意がないように見える。日本語由来の流行語なので、意味を知らない人も多い。", "vi": "Chỉ dùng trong tình huống nhẹ nhàng. Dùng ở nơi cần một lời xin lỗi thật sự thì sẽ bị coi là thiếu thành ý. Vì là từ thời thượng gốc Nhật nên nhiều người không biết nghĩa."}'::jsonb, 'Men-Go-Men-Go', '[{"type": "감탄사", "examples": [{"de": "Ah, ich bin zu spät — sorryyy~", "es": "Ay, llegué tarde, perdooón~", "ja": "あー遅れた、ごめんごめん〜", "vi": "Á trễ rồi, xin lỗiii~", "eng": "Ah, I''m late — sorryyy~", "kor": "아 늦었네 멘고멘고~"}], "definition": "일본어 「ごめん(고멘, 미안)」을 변형·반복해 귀엽게 만든 사과 표현으로 알려져 있다. 진지한 사과가 아니라 가벼운 실수에 장난스럽게 던지는 말이다. 다만 일본어에서 실제로 이렇게 쓰는지, 한국 인터넷에서 만들어진 형태인지는 출처마다 설명이 갈린다.", "definition_i18n": {"de": "Angeblich eine niedliche, verdoppelte Abwandlung des japanischen ごめん (gomen, „Entschuldigung“). Für kleine Patzer, nicht für echte Entschuldigungen. Ob Japanischsprechende das wirklich so sagen oder ob die Form im koreanischen Netz entstand, ist zwischen den Quellen strittig.", "en": "Reportedly a cute, doubled-up twist on Japanese ごめん (gomen, “sorry”). It''s for light slip-ups, not real apologies. Whether Japanese speakers actually say it this way or whether the form was coined on the Korean internet is disputed across sources.", "es": "Se dice que es un giro tierno y duplicado del japonés ごめん (gomen, “perdón”). Sirve para descuidos leves, no para disculpas de verdad. Si los japoneses lo dicen así realmente o si la forma nació en internet en Corea es algo que las fuentes discuten.", "ja": "日本語の「ごめん」を変形・反復してかわいくした謝罪表現とされる。真剣な謝罪ではなく、軽いミスにふざけて放つ言葉。ただし日本語で実際にこう使うのか、韓国のネットで作られた形なのかは出典によって説明が分かれる。", "vi": "Được cho là biến thể dễ thương, lặp đôi của tiếng Nhật ごめん (gomen, “xin lỗi”). Dùng cho lỗi nhỏ, không phải lời xin lỗi thật sự. Người Nhật có thật sự nói vậy hay dạng này do dân mạng Hàn tạo ra thì các nguồn nói khác nhau."}}]'::jsonb, array['아자스','야르','꺄르'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Sorryyy (playful)"}, {"lang": "🇯🇵 JA", "text": "ごめんごめん(おどけ)"}, {"lang": "🇨🇳 ZH", "text": "抱歉啦(玩笑)"}, {"lang": "🇻🇳 VI", "text": "Xin lỗi nha (đùa)"}, {"lang": "🇪🇸 ES", "text": "Perdooón (en broma)"}, {"lang": "🇩🇪 DE", "text": "Sorryyy (scherzhaft)"}]'::jsonb),
('443', '델룰루', 'new-slang', '될 거라고 믿어버리는 망상급 낙관', '[델룰루]', '{"de": "Wahnhafter Optimismus, an den man sich klammert", "en": "Delusional optimism you lean into on purpose", "es": "Optimismo delirante que eliges creerte", "ja": "あえて信じ込む妄想レベルの楽観", "vi": "Lạc quan hoang tưởng mà bạn cố tin"}'::jsonb, '영어 delusional을 귀엽게 줄인 인터넷 속어 delulu가 원말이다. 10여 년 전부터 글로벌 K팝 팬덤에서 아이돌과의 관계를 상상하는 팬을 놀리는 말로 쓰였고, 틱톡에서 「delulu is the solulu(망상이 곧 해결책)」라는 표현이 퍼지며 긍정적인 뜻이 덧붙었다. 2025년 케임브리지 사전에 등재됐다. 한국어 표기는 델룰루·딜루루·딜룰루가 섞여 쓰이며 아직 하나로 굳지 않았다.', '{"de": "Es stammt von delulu, der niedlichen Netzkurzform des englischen delusional. Über ein Jahrzehnt lang kursierte es im globalen K-Pop-Fandom als Spott für Fans, die sich eine Beziehung mit einem Idol ausmalen; auf TikTok gab die Wendung „delulu is the solulu“ ihm eine positive Wendung. Das Cambridge Dictionary nahm es 2025 auf. Die koreanische Schreibung ist noch offen — 델룰루, 딜루루 und 딜룰루 sind alle im Umlauf.", "en": "It comes from delulu, the cutesy internet clipping of English delusional. For over a decade it circulated in global K-pop fandom as a tease for fans who imagine a relationship with an idol; on TikTok the phrase “delulu is the solulu” added a positive spin. Cambridge Dictionary added it in 2025. The Korean spelling is still unsettled — 델룰루, 딜루루 and 딜룰루 all circulate.", "es": "Viene de delulu, el recorte cariñoso del inglés delusional. Durante más de una década circuló en el fandom global del K-pop como burla hacia quienes fantasean con salir con un ídolo; en TikTok la frase “delulu is the solulu” le dio un giro positivo. El Diccionario Cambridge lo incorporó en 2025. La grafía coreana sigue sin fijarse: conviven 델룰루, 딜루루 y 딜룰루.", "ja": "英語delusionalをかわいく縮めたネット俗語deluluが元。10年ほど前からグローバルなK-POPファンダムで、アイドルとの関係を想像するファンをからかう言葉として使われ、TikTokで「delulu is the solulu(妄想こそ解決策)」という表現が広まって肯定的な意味が加わった。2025年にケンブリッジ辞典に収録。韓国語表記はデルルル・ディルル・ディルルルが混在し、まだ一つに定まっていない。", "vi": "Bắt nguồn từ delulu, cách rút gọn dễ thương của từ tiếng Anh delusional. Hơn một thập kỷ qua nó lưu hành trong fandom K-pop toàn cầu như lời trêu những fan tưởng tượng hẹn hò với thần tượng; trên TikTok, câu “delulu is the solulu” thêm sắc thái tích cực. Từ điển Cambridge thu nạp nó năm 2025. Cách viết tiếng Hàn vẫn chưa thống nhất — 델룰루, 딜루루 và 딜룰루 cùng tồn tại."}'::jsonb, '자기한테 붙이면 「나도 알아, 근데 믿을래」라는 자조 섞인 농담이고, 남에게 붙이면 「현실 좀 봐」라는 놀림이 된다. 영어 밈에서 들어온 말이라 한국어 표기가 아직 흔들리고, 세대나 커뮤니티에 따라 못 알아듣는 사람도 많다.', '{"de": "Auf sich selbst gemünzt ein selbstironischer Scherz — „ich weiß, aber ich glaub''s trotzdem“; auf andere gemünzt ein Wink, realistisch zu werden. Weil es aus einem englischen Meme kam, schwankt die koreanische Schreibung noch, und je nach Alter und Community kennen es viele nicht.", "en": "About yourself it''s a self-aware joke — “I know, but I''m believing it anyway”; about someone else it''s a nudge to get real. Because it came in from an English meme, the Korean spelling is still wobbly and plenty of people, depending on age and community, won''t recognise it.", "es": "Sobre uno mismo es una broma autoconsciente —“ya lo sé, pero me lo creo igual”—; sobre otro, un toque para que baje a la realidad. Como llegó de un meme en inglés, la grafía coreana aún baila y bastante gente, según edad y comunidad, no lo reconoce.", "ja": "自分に使えば「わかってるけど信じる」という自嘲混じりの冗談、他人に使えば「現実を見なよ」というからかいになる。英語のミーム由来なので韓国語表記がまだ揺れており、世代やコミュニティによっては通じない人も多い。", "vi": "Nói về mình thì là đùa tự giễu — “biết rồi, nhưng vẫn cứ tin”; nói về người khác thì là nhắc họ tỉnh lại. Vì đến từ meme tiếng Anh, cách viết tiếng Hàn còn dao động và khá nhiều người, tùy tuổi và cộng đồng, sẽ không hiểu."}'::jsonb, 'Del-Lul-Lu', '[{"type": "명사·형용사", "examples": [{"de": "Ich hab das Gefühl, diesmal komme ich rein. Total delulu, aber ich glaub''s einfach.", "es": "Siento que esta vez entro. Delulu total, pero me lo voy a creer.", "ja": "今回は受かる気がする。デルルルだけど、信じることにする。", "vi": "Lần này mình thấy sẽ đậu. Delulu thật đấy, nhưng cứ tin thôi.", "eng": "I feel like I''ll get in this time. Total delulu, but I''m going with it.", "kor": "나 이번엔 붙을 것 같아. 델룰루지만 그냥 믿을래."}, {"de": "Delulu is the solulu — glaub dran, dann klappt''s.", "es": "Delulu is the solulu: si te lo crees, pasa.", "ja": "デルルルはソルルル、信じれば叶う。", "vi": "Delulu chính là solulu — tin là thành thật.", "eng": "Delulu is the solulu — believe it and it happens.", "kor": "델룰루가 솔룰루다, 믿으면 이루어져."}], "definition": "영어 delusional(망상적인)에서 온 말로, 현실적으로는 무리인 걸 알면서도 「나는 잘될 거야」라고 믿어버리는 태도. 원래 K팝 팬덤에서 「내가 최애랑 사귈 수 있다」는 상상을 놀리던 말이었는데, 지금은 불안을 버티는 생존 전략처럼 긍정적으로도 쓴다.", "definition_i18n": {"de": "Vom englischen delusional: bewusst glauben, „bei mir wird das schon klappen“, obwohl man weiß, dass es weit hergeholt ist. Es begann im K-Pop-Fandom als Spott über Fans, die von einer Beziehung mit ihrem Bias träumen, und hat sich seither ins Positive gedreht — eine Art, Angst in Schach zu halten.", "en": "From English delusional: choosing to believe “it''ll work out for me” even when you know it''s a stretch. It began in K-pop fandom as a tease for fans who imagine dating their bias, and has since flipped positive — a way of holding anxiety at bay.", "es": "Del inglés delusional: elegir creer que “a mí me va a salir bien” aun sabiendo que es mucho pedir. Nació en el fandom del K-pop como burla hacia quien fantasea con salir con su bias, y desde entonces ha girado a lo positivo: una forma de mantener a raya la ansiedad.", "ja": "英語のdelusional(妄想的)から来た語で、現実的には無理だと分かっていても「自分はうまくいく」と信じ込む態度。もとはK-POPファンダムで「推しと付き合える」という妄想をからかう言葉だったが、今では不安に耐えるための生存戦略として肯定的にも使う。", "vi": "Từ tiếng Anh delusional: cứ chọn tin rằng “rồi mình sẽ ổn” dù biết là hơi quá sức. Nó khởi từ fandom K-pop như lời trêu fan mơ hẹn hò với idol, rồi chuyển sang nghĩa tích cực — một cách giữ cho lo âu không lấn át."}}]'::jsonb, array['과몰입','최애','추구미'], array['딜루루','딜룰루','delulu'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Delulu (delusional optimism)"}, {"lang": "🇯🇵 JA", "text": "デルルル(妄想的楽観)"}, {"lang": "🇨🇳 ZH", "text": "妄想式乐观"}, {"lang": "🇻🇳 VI", "text": "Delulu (lạc quan hoang tưởng)"}, {"lang": "🇪🇸 ES", "text": "Delulu (optimismo delirante)"}, {"lang": "🇩🇪 DE", "text": "Delulu (wahnhafter Optimismus)"}]'::jsonb);

commit;

